class EarthlyRustLibWire implements BaseWire {
  factory EarthlyRustLibWire.fromExternalLibrary(ExternalLibrary lib) =>
      EarthlyRustLibWire(lib.ffiDynamicLibrary);

  /// Holds the symbol lookup function.
  final ffi.Pointer<T> Function<T extends ffi.NativeType>(String symbolName)
  _lookup;

  /// The symbols are looked up in [dynamicLibrary].
  EarthlyRustLibWire(ffi.DynamicLibrary dynamicLibrary)
    : _lookup = dynamicLibrary.lookup;
}
